def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    return float(math.log(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    moment = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x
            moment += x * r * r * r
    if total <= 0:
        return 0.0
    return float(4.0 * math.pi * moment / (3.0 * total * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    electrons = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z):
            total += x
            electrons += x * z
    return float(electrons / (total * v)) if total > 0 else 0.0

def feature(s):
    props = s.get('element_properties', {})
    records = []
    for e, x in s.get('composition', {}).items():
        p = props.get(e, {})
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x is None or x <= 0 or ionization is None or affinity is None:
            continue
        hardness = ionization - affinity
        chi = 0.5 * (ionization + affinity)
        if math.isfinite(hardness) and math.isfinite(chi) and hardness > 1e-6:
            records = records + [(x, chi, hardness)]
    norm = sum(t[0] for t in records)
    inverse_weight = sum(t[0] / t[2] for t in records)
    if norm <= 0 or inverse_weight <= 0:
        return 0.0
    center = sum(t[0] * t[1] / t[2] for t in records) / inverse_weight
    return float(sum(t[0] * (t[1] - center) ** 2 / t[2] for t in records) / norm)

